        var forceOutput = '';
        try {
            forceOutput = runCmd({ command: 'git push -u origin ' + branchName + ' --force' }) || '';
        } catch (forceErr) {
            forceOutput = String(forceErr);
        }
        var forceFailed = forceOutput.indexOf('remote rejected') !== -1 ||
