                return pr && pr.head && pr.head.ref === expectedBranch;
            })[0];
            if (existingPr) {
                    var existingUrl = existingPr.html_url || existingPr.url || ('#' + existingPr.number);
                    console.log('⚠️  PR already open for', ticketKey, ':', existingUrl, '— skipping re-development');
