                            'Source-code bugs must use CodeGraph before declaring the work blocked.\n\n' +
                            'Resetting to ' + commentMarkup.forTicket(ticketKey).bold('Ready For Development') + ' for an automatic retry.'
                    );
                } catch (e) {}
                try {
                    tracker.moveToStatus(ticketKey, statuses.READY_FOR_DEVELOPMENT);
                    console.log('✅ Moved', ticketKey, 'to Ready For Development for CodeGraph retry');
                } catch (e) {
                    console.warn('Failed to move ticket to Ready For Development:', e);
                }
                removeLabels(ticketKey, params, tracker);
                return { success: true, path: 'blocked_without_codegraph', ticketKey };
            }

            const m = commentMarkup.forTicket(ticketKey);
            let comment = m.h(3, '🚫 Bug Cannot Be Fixed Automatically') + '\n\n';
            comment += m.bold('Reason') + ': ' + (blocked.reason || '(see details below)') + '\n\n';
            if (blocked.tried && blocked.tried.length > 0) {
                comment += m.bold('Attempted') + ':\n';
                blocked.tried.forEach(function(t) { comment += '- ' + t + '\n'; });
                comment += '\n';
            }
            if (blocked.needs) {
                comment += m.bold('Needs from human') + ': ' + blocked.needs + '\n';
            }

            try { tracker.postComment(ticketKey, comment); } catch (e) {}

            try {
                tracker.moveToStatus(ticketKey, jiraConfig.statuses.BLOCKED);
                console.log('✅ Move…

/**
 * Node-based test harness for agent unit tests.
 *
 * Mirrors the GraalJS testRunner API so the same test files can be executed
 * in environments where the dmtools JSRunner is not available.
 * Provides: test(), suite(), assert, loadModule(), makeRequire(), trackersMock()
 */

const fs = require('fs');
const path = require('path');

var _results_ = { passed: 0, failed: 0, errors: [] };
var _currentSuite_ = 'default';

function test(name, fn) {
    var fullName = _currentSuite_ + ' > ' + name;
    try {
        fn();
        _results_.passed++;
        console.log('  ✅ ' + fullName);
    } catch (e) {
        _results_.failed++;
        var msg = e.message || String(e);
        _results_.errors.push({ name: fullName, error: msg });
        console.log('  ❌ ' + fullName);
        console.log('     ' + msg);
    }
}

function suite(name, fn) {
    var prev = _currentSuite_;
    _currentSuite_ = name;
    console.log('\n── ' + name + ' ──');
    fn();
    _currentSuite_ = prev;
}

var assert = {
    equal: function(actual, expected, msg) {
        if (actual !== expected) {
            throw new Error(
                (msg ? msg + ': ' : '') +
                'expected ' + JSON.stringify(expected) + ' but got ' + JSON.stringify(actual)
            );
        }
    },
    notEqual: function(actual, unexpected, msg) {
        if (actual === unexpected) {
            throw new Error(
                (msg ? msg + ': ' : '') +
                'expected value to not equal ' + JSON.stringify(unexpected)
            );
        }
    },
    deepEqual: function(actual, expected, msg) {
        var a = JSON.stringify(actual);
        var b = JSON.stringify(expected);
        if (a !== b) {
            throw new Error(
                (msg ? msg + ': ' : '') +
                '\n  expected: ' + b +
                '\n  actual:   ' + a
            );
        }
    },
    ok: function(val, msg) {
        if (!val) {
            throw new Error(msg || ('expected truthy, got: ' + JSON.stringify(val)));
        }
    },
    notOk: function(val, msg) {
        if (val) {
            throw new Error(msg || ('expected falsy, got: ' + JSON.stringify(val)));
        }
    },
    contains: function(str, substr, msg) {
        if (typeof str !== 'string' || str.indexOf(substr) === -1) {
            throw new Error(
                (msg ? msg + ': ' : '') +
                JSON.stringify(str) + ' does not contain ' + JSON.stringify(substr)
            );
        }
    },
    notContains: function(str, substr, msg) {
        if (typeof str === 'string' && str.indexOf(substr) !== -1) {
            throw new Error(
                (msg ? msg + ': ' : '') +
                JSON.stringify(str) + ' should not contain ' + JSON.stringify(substr)
            );
