 * cold-reset path unchanged.
 */
function recoverMissingResponse(ticketKey, customParams, developmentSummary, cliHasFatalError, cliErrorMessage) {
    if (isFatalCliEnvironmentError(developmentSummary, cliHasFatalError)) {
