        ticketKey: ticketKey,
        customParams: customParams
    });
    if (!resume.attempted) {
        console.log('Bounded resume for the missing deliverable not attempted (' + (resume.reason || 'disabled') + ') — continuing to the existing reset path.');
        return null;
    }
