function performGitOperations(branchName, commitMessage, baseBranch, config, customParams, ticketKey) {
  try {
      submoduleHelper.pushManagedSubmodules({ ...unchanged... });

      try {
          gitStaging.untrackRuntimeArtifacts(function (command) { return runCmd({ command: command });
      } catch (cleanupErr) {
          console.warn('Could not remove tracked Copilot session cache before staging:', cleanupErr);
      }

      console.log('Staging working tree (check-ignore probe-filtered exclusions)...');
      runCmd({ command: 'git add . -- ' + gitStaging.buildStagingPathspecs(runCmd, ['factory-kit']) });

      const statusOutput = prHelper.readStagedDiffStat(function (command) { return runCmd({ command: command }); }, _workingDir);

      if (!hasStagedChanges(statusOutput)) {
          return resolveNothingStagedOutcome(function (command) { return runCmd({ command: command }); }, branchName, baseBranch);
      }

      var safeMessage = sanitizeCommitMessage(commitMessage);
      console.log('Commiting changes...');
      runCmd({ command: 'git commit -m "' + safeMessage + '"' });

      var syncResult = prHelper.syncBranchWithBase({ ...unchanged... });
      if (!syncResult.success) {
          return { success: false, isMergeSyncFailure: true, error: syncResult.error };
      }

      console.log('Pushing to remote...');
      const pushAttempt = pushBranchToRemote(function (command) { return runCmd({ command: command }); }, branchName);
      const pushOutput = pushAttempt.output;
      const pushThrewException = pushAttempt.threw;

      const pushFailed = detectPushFailure(pushOutput, pushThrewException);
      if (pushFailed) {
          return { success: false, isPushFailure: true, error: 'Push was rejected by remote: ' + pushOutput.substring(0, 500) };
      }

      console.log('Verifying branch is pushed to remote...');
      const lsRemoteOutput = runCmd({ command: 'git ls-remote --heads origin ' + branchName }) || '';
      if (branchMissingOnRemote(lsRemoteOutput, branchName)) {
          return { success: false, isPushFailure: true, error: 'Branch was not found on remote after push' };
      }

      console.log('✅ Git operations completed successfully');
      return { success: true, branchName: branchName };
  } catch (error) {
      console.error('Git operations failed:', error);
      return { success: false, error: error.toString() };
  }
```

