      runCmd({ command: 'git add . -- ' + gitStaging.buildStagingPathspecs(runCmd, ['factory-kit']) });

      const statusOutput = prHelper.readStagedDiffStat(function (command) { return runCmd({ command: command }); }, _workingDir);

      if (!hasStagedChanges(statusOutput)) {
          return resolveNothingStagedOutcome(function (command) { return runCmd({ command: command }); }, branchName, baseBranch);
      }

      var safeMessage = sanitizeCommitMessage(commitMessage);
      console.log('Commiting changes...');
      runCmd({ command: 'git commit -m "' + safeMessage + '"' });

      var syncResult = prHelper.syncBranchWithBase({ ...unchanged... });
      if (!syncResult.success) {
          return { success: false, isMergeSyncFailure: true, error: syncResult.error };
      }

      console.log('Pushing to remote...');
      const pushAttempt = pushBranchToRemote(function (command) { return runCmd({ command: command }); }, branchName);
      const pushOutput = pushAttempt.output;
