 * so the escape chain is unit-testable in isolation. The replace order is
 * behaviour (each escape feeds the next), kept verbatim.
 */
function sanitizeCommitMessage(message) {
    return message
        .replace(/"/g, '\\"')
        .replace(/[><|;`$\r\n]/g, ' ')
        .replace(/\s+/g, ' ')
        .trim();
}

/**
