    const m = commentMarkup.forTicket(ticketKey);
    let comment = m.h(3, '✅ Bug Already Fixed') + '\n\n';
    if (alreadyFixed.rca) {
        comment += m.bold('Root Cause') + ': ' + alreadyFixed.rca + '\n\n';
    }
    if (alreadyFixed.commit) {
