function detectPushFailure(output, threwException) {
    if (threwException) {
        return true;
    }
    var markers = ['remote rejected', 'GH013', 'error: failed to push', 'push declined', 'non-fast-forward', 'rejected'];
    for (var i = 0; i < markers.length; i++) {
