 * same listPrs('open') shape, same head.ref match, null-tolerant.
 */
function findOpenPrForBranch(openPrs, expectedBranch) {
    return (openPrs || []).filter(function(pr) {
        return pr && pr.head && pr.head.ref === expectedBranch;
    })[0];
}

/**
